function createPool(size, runTask) {
  let running = 0, peak = 0;
  return {
    run(job) {
      running++;
      peak = Math.max(peak, running);
      return runTask(job).finally(() => { running--; });
    },
    stats() { return { running, queued: 0, peak }; },
  };
}

